package com.github.ydewolf.ysoulmana.content.mana;import com.github.ydewolf.ysoulmana.api.entity.EntityManaPool;import com.github.ydewolf.ysoulmana.config.SoulManaConfig;public class PlayerMana extends EntityManaPool implements IPlayerMana {    private float totalManaUsed = 0.0f;    private int regenCooldown = 0;    @Override    public float getTotalManaUsed() {        return this.totalManaUsed;    }    @Override    public void setTotalManaUsed(float mana) {        this.totalManaUsed = mana;    }    @Override    public void addTotalManaUsed(float amount) {        this.totalManaUsed += amount;    }    public boolean consumeMana(float amount) {        if (this.canConsumeMana(amount)) {            this.addTotalManaUsed(amount);            this.setMana(this.mana - amount);            return true;        }        return false;    }    @Override    public void copyFrom(IPlayerMana source) {        this.totalManaUsed = source.getTotalManaUsed();        super.copyFrom(source);    }    public int getRegenCooldown() {        return regenCooldown;    }    public void setRegenCooldown(int regenCooldown) {        this.regenCooldown = Math.max(0, regenCooldown);    }    public void decrementRegenCooldown() { this.setRegenCooldown(getRegenCooldown() - SoulManaConfig.manaRegenTickRate);}    public boolean onRegenCooldown() {        return this.getRegenCooldown() > 0;    }}